def the_readback(case, data):
    """RB — THE READBACK TABLE (THE LOOP's step 6 — the forms on file, no new form): twelve rows one per verse, graded against the kin's cells by CALL and the tape's lines by kind; the six rows SUPPLIED with their writes; THE RECEIPT ROW 34:9; THE THREE POINTER ROWS 34:4, 34:5, 34:6 (the song's two and the blessing's one PAID); the chapter's pasts reference rows; NO state, open or stretch row; NO marker — the thirty days a duration"""
    del P_[:]
    ask = case['ask']
    R = data['the_readback']['value']
    if ask == 'the_table':
        ink('34:1-12', 'twelve verses, %d rows; the grades %s' % (len(R), dict(collections.Counter(r['grade'] for r in R))))
        dat('the table a DATA row (the_readback); every row has kin — by CALL %d, on the tape %d' % (sum(1 for r in R if r['cell']), sum(1 for r in R if r['tape_kind'])))
        return out('the readback table (34:1-12) — %d rows one per verse, %s; every row graded against its kin' % (len(R), ', '.join('%s %d' % kv for kv in sorted(collections.Counter(r['grade'] for r in R).items()))), ['accepted'])
    if ask == 'the_supplied_rows':
        sup = [r['verses'] for r in R if r['grade'] == 'SUPPLIED']
        ink('34:1-12', "the SUPPLIED rows %s — the six lines' first verses" % (sup,))
        dat("the six lines' first verses SUPPLIED with their writes — the ascent, the oath, the death, the years, Joshua, the epilogue: the code's holes compiled at Moses' last day on the ledgers of moses, israel_people and yehoshua")
        return out("the supplied rows — %s: the six lines' first verses, the code's holes compiled at Moses' last day" % (', '.join(sup),), ['accepted'])
    if ask == 'the_reference_rows':
        ref = [(r['verses'], r['tape_kind'], r['tape_verse']) for r in R if r['tape_kind']]
        ink('34:1, 34:4-5, 34:7-12', 'the reference rows %s' % (ref,))
        dat("the T1 rows against the tape's lines by kind and first verse — the summons (32:48), Exodus 33:1's oath (Exodus 32:19's aftermath), Aaron's death and his thirty days (Numbers 20:28-29), the commission (Numbers 27:22), the prophet's law (18:15), the signs (Exodus 4:2), the tablets broken (Exodus 32:19): retellings and executions, never a second act")
        return out("the reference rows — %d against the tape's lines (the chapter's pasts — the summons, the oath, Aaron's death and his thirty days, the commission, the prophet's law, the signs, the tablets broken): run citations, never a second act" % (len(ref),), ['accepted'])
    if ask == 'the_receipts':
        rc = data['the_receipts']['value']
        ink('34:9', "the receipt seats by the formula's own finder %s — ONE in the chapter: 'as the LORD commanded Moses', the tabernacle's formula at its last Torah seat; the register file's seat 'Deut 34:9' declared class NONE for a book unread — RE-DECLARED at this compile from the gate's print; THE THREE POINTER ROWS 34:4, 34:5, 34:6 PAID (grade R)" % (rc,))
        dat("one receipt in the chapter (the formula's seats over Deut 34 -> ['Deut 34:9']); no footer, no header (the end of a book is not a footer — THE BOOK'S EDGE a DATA row); the register's seat re-declared (THE DATA ROW the_receipt_re_declared); THE POINTER ROWS 34:4 and 34:5 (the song's owed pointers) and 34:6 (the blessing's) PAID; the Prophets' seats (Joshua 1:1, 1:11, 4:14, 4:19, 5:12) cited never read")
        return out("the receipts (34:1-12) — one by the finder's own count, the receipt at 34:9 ('as the LORD commanded Moses' — the register's seat re-declared from the gate's print, its referent the commission behind on the tape); the three pointer rows 34:4, 34:5, 34:6 paid; no footer — the book's edge", ['accepted'])
    if ask == 'the_state_and_the_pointers':
        ink('34:4, 34:5, 34:6', 'state rows %s, pointer rows %s, open rows %s, stretch rows %s' % ([r['verses'] for r in R if r['state']], [r['verses'] for r in R if r['pointer']], [r['verses'] for r in R if r['open']], [r['verses'] for r in R if r['stretch']]))
        dat("NO STATE ROW — no two-armed condition in the death's chapter; THE THREE POINTER ROWS 34:4 (the two denials — 32:52's owed pointer), 34:5 (Aaron's death's words — 32:50's owed pointer) and 34:6 (the grave in Gad's portion — 33:21's owed pointer), grade R — the song's two and the blessing's one PAID; no open row (who wrote 'and Moses died there' a DATA row with both arms, not an open row), no stretch")
        return out("the pointer rows at 34:4, 34:5 and 34:6 (the song's two owed pointers and the blessing's one PAID — grade R); no state row (no two-armed condition); no open, no stretch row — the forms on file, no new form", ['accepted'])
    if ask == 'the_twin_diffed':
        ink('34:1-12', 'the twins diffed on the DB %s' % (TWIN,))
        dat("the reading's kin asserts read again (DP3) — 34:4 with Exodus 33:1 nine in order, 34:1 with 32:49 eight shared, 34:9 with Numbers 27:23 six, 34:7 with 31:2 five; the twins by sense without a shared token (34:5 with 32:50, 34:6 with 33:21, 34:12 with 9:17) unlinked but by the teachers' own joins (the Sifrei's, Onkelos's)")
